from .api.exceptions import PlanNotFound, UnexpectedResponse


class Configuration:
    CONFIGURATION_TYPE: str

    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        if not hasattr(cls, 'CONFIGURATION_TYPE'):
            raise AttributeError(f"{cls.__name__!r} must have a 'CONFIGURATION_TYPE' attribute")

    def __init__(self, api, name, description=None, conf_id=None):
        """
        :param CmDataRepositoryWebServiceAPI api:
        :param string name:
        :param string description:
        :param int conf_id:
        """
        self.cm_editor = api
        self.name = name
        self.description = description
        self.conf_id = conf_id

    @classmethod
    def get(cls, api):
        """
        Get configuration from CM Editor and creates Configuration object from it.

        :param CmDataRepositoryWebServiceAPI api:
        :rtype: Configuration
        """
        response = api.get_configurations(cls.CONFIGURATION_TYPE, filter_type='type')
        return cls(api, name=response['name'], description=response['description'], conf_id=response['configuration']['confId'])

    def __repr__(self):
        return f'{self.name} (type = {self.CONFIGURATION_TYPE}, conf_id = {self.conf_id}): {self.description}'


class Plan(Configuration):
    CONFIGURATION_TYPE = 'PLAN'

    @staticmethod
    def get(api, name):
        """
        Get plan from CM Editor and creates Plan object from it.

        :param CmDataRepositoryWebServiceAPI api:
        :param string name: plan name
        :rtype: Plan
        """
        try:
            response = api.get_configurations(name, filter_type='name')
        except UnexpectedResponse:
            raise PlanNotFound(f'Plan {name} not found')
        return Plan(api, response['name'], description=response['description'], conf_id=response['configuration']['confId'])

    def create(self):
        """
        Create plan in CM Editor.
        """
        response = self.cm_editor.create_configuration(self.CONFIGURATION_TYPE, self.name, description=self.description)
        self.conf_id = response['configuration']['confId']

    def edit(self, name=None, description=None):
        """
        Update plan name and description in CM Editor.
        """
        self.name = name or self.name
        self.description = description or self.description
        self.cm_editor.update_configuration(self.conf_id, self.CONFIGURATION_TYPE, self.name, description=self.description)

    def delete(self):
        """
        Delete plan from CM Editor.
        """
        self.cm_editor.delete_configuration(self.conf_id)


class Actual(Configuration):
    CONFIGURATION_TYPE = 'ACTUAL'


class Reference(Configuration):
    CONFIGURATION_TYPE = 'REFERENCE'
